add_filter( 'wp_mail_from', 'perfectpixel_outgoing_email_address', 20 );
add_filter( 'wp_mail_from_name', 'perfectpixel_outgoing_email_name', 20 );

function perfectpixel_outgoing_email_address( $from ) {
	$address = sanitize_email( '{{email_sender_address}}' );
	// Only replace WordPress' own default sender (wordpress@domain).
	if ( $address && is_email( $address ) && 0 === stripos( $from, 'wordpress@' ) ) {
		return $address;
	}
	return $from;
}

function perfectpixel_outgoing_email_name( $name ) {
	if ( 'WordPress' !== $name ) {
		return $name;
	}
	$custom = trim( '{{email_sender_name}}' );
	return $custom ? $custom : wp_specialchars_decode( get_bloginfo( 'name' ), ENT_QUOTES );
}
